# A meter's name used to be whose it is («Виктор», «Общий счётчик»); now it is what it measures.
NAMES = {
    'electricity': 'Электричество', 'water': 'Вода холодная', 'sewage': 'Вода холодная',
    'hot_water': 'Вода горячая', 'hot_water_heating': 'Вода горячая', 'gas': 'Газ', 'heating': 'Отопление',
}


def name_by_kind(apps, schema_editor):
    Meter = apps.get_model('billing', 'Meter')
    for meter in Meter.objects.all():
        receipt = meter.receipts.first()
        kind = meter.kind or (receipt.kind if receipt else '')
        if kind in NAMES:
            meter.kind, meter.name = ('water' if kind == 'sewage' else 'hot_water' if kind == 'hot_water_heating' else kind), NAMES[kind]
        else:
            meter.kind, meter.name = 'custom', (receipt.name if receipt and receipt.name else 'Счётчик')
        meter.save(update_fields=['kind', 'name'])


def name_by_owner(apps, schema_editor):
    Meter = apps.get_model('billing', 'Meter')
    for meter in Meter.objects.select_related('tenant'):
        meter.name = meter.tenant.name if meter.tenant_id else 'Общий счётчик'
        meter.save(update_fields=['name'])


